/**
 * Sample databases for the SQL practice area and SQL lessons.
 * The .sql seed files are generated by scripts/generate-datasets.mjs (deterministic)
 * and loaded lazily, so they are not part of the main bundle.
 */
export type DatasetId = 'retail' | 'hr' | 'inventory'

export interface DatasetTable {
  name: string
  description: string
}

export interface Dataset {
  id: DatasetId
  title: string
  description: string
  tables: DatasetTable[]
  starter: string
  load: () => Promise<string>
}

export const datasets: Dataset[] = [
  {
    id: 'retail',
    title: 'Retail sales',
    description:
      'A UK homeware and electronics retailer selling online, in-store and through a mobile app. Two years of orders (2023-2024). Prices in GBP.',
    tables: [
      { name: 'customers', description: 'One row per customer: name, email (sometimes missing), city, country, signup date and segment.' },
      { name: 'products', description: 'Product catalogue with category, selling price and cost.' },
      { name: 'orders', description: 'One row per order: customer, date, channel (Online, In-store, Mobile App) and status (Completed, Returned, Cancelled).' },
      { name: 'order_items', description: 'Order lines: which product, quantity, the price charged and any discount (0.1 = 10%).' },
    ],
    starter: `-- Five most recent orders\nSELECT order_id, customer_id, order_date, channel, status\nFROM orders\nORDER BY order_date DESC\nLIMIT 5;`,
    load: () => import('./retail.sql?raw').then((m) => m.default),
  },
  {
    id: 'hr',
    title: 'HR and people',
    description: 'A 160-person company across eight departments, with managers, salaries, leavers and yearly performance ratings (1-5).',
    tables: [
      { name: 'departments', description: 'Department name and office location.' },
      { name: 'employees', description: 'Job title, department, manager (manager_id points to another employee), hire date, salary and termination date (NULL if still employed).' },
      { name: 'performance_reviews', description: 'One rating per employee per year, 2021-2024.' },
    ],
    starter: `-- Headcount by department (current employees only)\nSELECT d.department_name, COUNT(*) AS headcount\nFROM employees e\nJOIN departments d ON d.department_id = e.department_id\nWHERE e.termination_date IS NULL\nGROUP BY d.department_name\nORDER BY headcount DESC;`,
    load: () => import('./hr.sql?raw').then((m) => m.default),
  },
  {
    id: 'inventory',
    title: 'Inventory and suppliers',
    description: 'Four warehouses, eight suppliers, current stock levels and two years of purchase orders, including late and partial deliveries.',
    tables: [
      { name: 'warehouses', description: 'Warehouse name, city and capacity.' },
      { name: 'suppliers', description: 'Supplier country and promised lead time in days.' },
      { name: 'products', description: 'SKU, category, supplier, unit cost and reorder level.' },
      { name: 'stock_levels', description: 'Units on hand per product per warehouse, with the reorder point.' },
      { name: 'purchase_orders', description: 'Orders placed with suppliers: expected vs received date and quantity (received_date is NULL while open).' },
    ],
    starter: `-- Products below their reorder point\nSELECT w.warehouse_name, p.product_name, s.quantity_on_hand, s.reorder_point\nFROM stock_levels s\nJOIN products p ON p.product_id = s.product_id\nJOIN warehouses w ON w.warehouse_id = s.warehouse_id\nWHERE s.quantity_on_hand < s.reorder_point\nORDER BY s.quantity_on_hand;`,
    load: () => import('./inventory.sql?raw').then((m) => m.default),
  },
]

export const getDataset = (id: string) => datasets.find((d) => d.id === id) ?? datasets[0]
